  async function loadCapabilities() {const t=ticket('cap');try{const cap=await json('/api/capabilities');if(!current(t))return;state.auth.mode=cap.auth_mode||'dev';state.auth.loginRequired=!!cap.login_required;if(state.auth.mode==='password'){if(!state.auth.token){state.cap=null;showLogin();return;}if(!cap.upload_limits){handleSessionExpired();return;}if(!state.auth.user){try{await loadMe();}catch(e){if(!current(t))return;if(e.code==='CONNECTION')errorNotice(e);return;}if(!current(t))return;}hideLogin();}else{hideLogin();}renderAuthUI();state.cap=cap;if(!state.importMode)state.importMode=cap.revision_ruleset_version?'revision':'readonly';$('upload-limit').textContent=`仅接收 DOCX · 单文件 ≤ ${size(cap.upload_limits.max_file_bytes)}`;$('auth-note').textContent=state.auth.mode==='dev'?'开发身份通过请求头进行隔离。生产身份服务尚未配置时将关闭访问。':'当前环境使用账号登录，请求通过 Bearer 令牌进行身份隔离。';const revision=cap.revision_ruleset_version?`<dt>合同修订规则</dt><dd>${esc(cap.revision_ruleset_version)} · ${cap.revision_mode==='delivery'?'正式交付':'评测模式'} · 支持 ${cap.revision_actions_total} 项</dd>`:'';$('capability-details').innerHTML=`<dt>只读诊断规则</dt><dd>${esc(cap.ruleset_version)}</dd>${revision}<dt>业务动作总数</dt><dd>${cap.actions_total} 项</dd><dt>正式自动写入</dt><dd>${cap.auto_write_count} 项（合同修订写入 ${cap.revision_auto_write_enabled?'已开启':'未开启'}）</dd><dt>单文件限制</dt><dd>${size(cap.upload_limits.max_file_bytes)}</dd>`;updateDeliveryNote();renderImport();}catch(e){if(current(t)){state.cap=null;errorNotice(e);}}}
  function deliveryCounts() {const dc=state.task?.delivery_counts;if(dc)return dc;const docs=[...(state.progressDocs||[]),...(state.resultDocs||[])];if(!docs.length)return null;const counts={complete:0,complete_with_exceptions:0,incomplete:0,not_generated:0,evaluation_modified:0,evaluation_modified_with_exceptions:0,evaluation_unmodified:0};for(const d of docs)if(d.delivery_status in counts)counts[d.delivery_status]+=1;return counts;}
