  function resetImportStages(task=null) {$('upload-message').textContent=task?'重新选择未接收的本地文件；按原名与大小匹配，已接收文件无需再次选择。':'选择或拖入 DOCX 合同，确认文件清单后创建任务。';}
  function newTask() {if(state.uploading)return;state.recover=null;state.imports=[];state.createKey=null;state.importPage=1;$('task-name').value='';resetImportStages();renderImport();go('import');$('task-name').focus();}
