  async function exportResults(){const id=state.selected;if(!id)return;const button=document.querySelector('[data-action="export-results"]');if(button)button.disabled=true;const t=ticket('export');try{const values={q:$('result-search').value.trim(),eligibility:$('qualification-filter').value,job_status:$('processing-filter').value,delivery_status:$('completeness-filter').value,error_code:$('reason-filter').value,sort:$('result-sort').value,page_size:200,page:1};let all=[],total=Infinity,page=1;while(all.length<total&&page<=100){const p=await json(`${pathTask(id)}/documents?${param({...values,page})}`);if(!current(t)||state.selected!==id)return;all.push(...p.items);total=p.total;if(!p.items.length)break;page++;}const rows=[['序号','文件名','资格','处理状态','交付完整性','业务提示','原始原因码']].concat(all.map((d,i)=>[i+1,d.name,labels[d.eligibility||'pending']||'未判定',labels[d.job_status]||d.job_status,labels[d.delivery_status]||d.delivery_status,docReason(d),(d.reason_codes||[]).join('；')||d.error_code||'']));const csv='\ufeff'+rows.map(r=>r.map(csvEscape).join(',')).join('\r\n');downloadText(csv,`${state.task?.name||'任务'}_结果清单.csv`);toast(`已导出 ${all.length} 条结果清单（状态清单，不是合同交付）`);}catch(e){if(current(t))errorNotice(e,'导出失败：');}finally{if(button)button.disabled=false;}}
