  for(const [name,ids] of [['task',['task-filter','task-sort']],['import',['import-filter']],['progress',['progress-filter','progress-sort']],['result',['qualification-filter','processing-filter','completeness-filter','reason-filter','result-sort']]])for(const id of ids)$(id).addEventListener('change',()=>changed(name));
  for(const id of ['progress-task','result-task'])$(id).addEventListener('change',e=>selectTask(e.target.value,false));
  document.addEventListener('change',e=>{if(e.target.id==='import-mode'){state.importMode=e.target.value;renderImport();return;}const name=e.target.dataset.pagesize;if(name){state[`${name}Size`]=Number(e.target.value);changed(name);}});$('dev-user').addEventListener('input',identityChanged);$('task-name').addEventListener('input',()=>{if(!$('task-name-error').hidden)nameError(true);});$('detail-body').addEventListener('click',e=>{const quote=e.target.closest('.evidence.quote');if(quote&&!e.target.closest('a,button'))quote.classList.toggle('expanded');});$('close-detail').addEventListener('click',closeDetail);$('detail-overlay').addEventListener('click',e=>{if(e.target===$('detail-overlay'))closeDetail();});document.addEventListener('keydown',e=>{if($('detail-overlay').hidden)return;if(e.key==='Escape'){closeDetail();return;}if(e.key==='Tab'){const nodes=[...$('detail-overlay').querySelectorAll('button,summary,a[href],input,select')].filter(n=>!n.disabled&&n.offsetParent!==null),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
  window.addEventListener('hashchange',()=>{if(location.hash.slice(1)!==state.view)go(location.hash.slice(1));});document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&document.title!==BASE_TITLE)document.title=BASE_TITLE;});try{$('dev-user').value=localStorage.getItem('fundlex-dev-user') || 'local-user';}catch{$('dev-user').value='local-user';}state.auth.token=storedToken();state.auth.user=storedUser();$('login-form').addEventListener('submit',submitLogin);$('logout-btn').addEventListener('click',logout);$('password-btn').addEventListener('click',openPasswordDialog);$('pwd-cancel').addEventListener('click',closePasswordDialog);$('password-form').addEventListener('submit',submitPasswordChange);$('password-view').addEventListener('click',e=>{if(e.target===$('password-view'))closePasswordDialog();});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('password-view').hidden)closePasswordDialog();});renderAuthUI();renderTask();renderImport();go(location.hash.slice(1));refresh(true);setInterval(()=>{if(state.task&&state.cap&&!state.uploading&&document.visibilityState==='visible'&&(['uploading','queued','running','paused'].includes(state.task.status)))refresh(true);},5000);
